envelope.source:
grammar Phantom version "1.0.0" edition 2 {
  word = 1*( %x41-5A / %x61-7A )
  digit = 1*( %x30-39 )
  base = ( word ) as code
  other = ( digit ) as other_code
  item = ( base / other )
  identifier = ( ( 1*( item ) ) as items )
  entry identifier: identifier
  bindings identifier {
    code -> items[].code (string)
  }
}
